import{_ as d,o as r,c as a,a2 as i}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"2.7 常用电工名词与单位速查","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-7-chang-yong-dian-gong-ming-ci-yu-dan-wei-su-cha.md","filePath":"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-7-chang-yong-dian-gong-ming-ci-yu-dan-wei-su-cha.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/02-chapter-2-dian-gong-ji-chu-zhi-shi/2-7-chang-yong-dian-gong-ming-ci-yu-dan-wei-su-cha.md"};function o(e,t,n,h,s,g){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="_2-7-常用电工名词与单位速查" tabindex="-1">2.7 常用电工名词与单位速查 <a class="header-anchor" href="#_2-7-常用电工名词与单位速查" aria-label="Permalink to &quot;2.7 常用电工名词与单位速查&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>这一节是&quot;查字典&quot;——把电工最常用的<strong>名词</strong>和<strong>单位</strong>整理成表,方便你随时翻、反复背。学习后面章节时遇到&quot;这个词是什么意思、单位是什么&quot;,都可以回到这里查。</p><h2 id="一、常用电工名词速查" tabindex="-1">一、常用电工名词速查 <a class="header-anchor" href="#一、常用电工名词速查" aria-label="Permalink to &quot;一、常用电工名词速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名词</th><th>符号</th><th>定义(通俗版)</th><th>单位</th></tr></thead><tbody><tr><td>电流</td><td>I</td><td>电荷定向移动形成的电流</td><td>安培(A)</td></tr><tr><td>电压</td><td>U</td><td>两点间的电位差,推动电流的力量</td><td>伏特(V)</td></tr><tr><td>电动势</td><td>E</td><td>电源内部产生电压的能力</td><td>伏特(V)</td></tr><tr><td>电阻</td><td>R</td><td>导体对电流的阻碍作用</td><td>欧姆(Ω)</td></tr><tr><td>电阻率</td><td>ρ</td><td>反映材料导电性能的物理量</td><td>欧姆·米(Ω·m)</td></tr><tr><td>电功(电能)</td><td>W</td><td>电流做的功,电能转化量</td><td>焦耳(J)、千瓦时(kWh)</td></tr><tr><td>电功率</td><td>P</td><td>单位时间做的功,用电快慢</td><td>瓦特(W)</td></tr><tr><td>焦耳定律热量</td><td>Q</td><td>电流通过导体产生的热量</td><td>焦耳(J)</td></tr><tr><td>周期</td><td>T</td><td>交流电完成一次完整变化的时间</td><td>秒(s)</td></tr><tr><td>频率</td><td>f</td><td>每秒变化的次数</td><td>赫兹(Hz)</td></tr><tr><td>幅值/最大值</td><td>Um</td><td>交流电波形最高值</td><td>伏特(V)</td></tr><tr><td>有效值</td><td>U</td><td>交流电等效的直流值(220/380 即有效值)</td><td>伏特(V)</td></tr><tr><td>相位</td><td>φ</td><td>交流电某一时刻的角度位置</td><td>度(°)/弧度(rad)</td></tr><tr><td>感抗</td><td>XL</td><td>电感对交流电的阻碍</td><td>欧姆(Ω)</td></tr><tr><td>容抗</td><td>XC</td><td>电容对交流电的阻碍</td><td>欧姆(Ω)</td></tr><tr><td>磁通量</td><td>Φ</td><td>穿过某面积磁感线的多少</td><td>韦伯(Wb)</td></tr><tr><td>磁感应强度</td><td>B</td><td>描述磁场强弱的量</td><td>特斯拉(T)</td></tr><tr><td>功率因数</td><td>cosφ</td><td>有功功率与视在功率之比</td><td>无(比值)</td></tr><tr><td>绝缘电阻</td><td>—</td><td>设备绝缘材料的电阻,越高越安全</td><td>兆欧(MΩ)</td></tr></tbody></table><h2 id="二、单位换算速查" tabindex="-1">二、单位换算速查 <a class="header-anchor" href="#二、单位换算速查" aria-label="Permalink to &quot;二、单位换算速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>换算</th><th>关系</th></tr></thead><tbody><tr><td>电流</td><td>1 A = 1000 mA = 10⁶ μA</td></tr><tr><td>电压</td><td>1 kV = 1000 V,1 V = 1000 mV</td></tr><tr><td>电阻</td><td>1 MΩ = 1000 kΩ = 10⁶ Ω</td></tr><tr><td>功率</td><td>1 kW = 1000 W</td></tr><tr><td>电能</td><td><strong>1 度电 = 1 kWh = 3.6 × 10⁶ J</strong></td></tr><tr><td>频率</td><td>工频 = 50 Hz,周期 = 0.02 s</td></tr><tr><td>交流电</td><td>有效值 × √2 ≈ 最大值;有效值 = 最大值/√2 ≈ 0.707 倍</td></tr><tr><td>三相星形</td><td>线电压 = √3 × 相电压(√3 ≈ 1.732)</td></tr><tr><td>三相三角形</td><td>线电流 = √3 × 相电流</td></tr></tbody></table><h2 id="三、易混单位-概念对照" tabindex="-1">三、易混单位/概念对照 <a class="header-anchor" href="#三、易混单位-概念对照" aria-label="Permalink to &quot;三、易混单位/概念对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>易混项</th><th>区别</th></tr></thead><tbody><tr><td>W(瓦特) vs W(电功)</td><td>瓦特是功率单位;电功用 W 表示,单位是焦耳(J)</td></tr><tr><td>电压 U vs 电动势 E</td><td>电动势是电源内部的&quot;能力&quot;,电压是两点的&quot;电位差&quot;</td></tr><tr><td>有效值 vs 最大值</td><td>220 V 是有效值,最大值约 311 V</td></tr><tr><td>相电压 vs 线电压</td><td>火线对零线=相电压(220),火线对火线=线电压(380)</td></tr><tr><td>感抗 vs 容抗</td><td>电感通直阻交;电容通交阻直</td></tr><tr><td>短路 vs 断路</td><td>短路电流巨大(危险),断路无电流(停用)</td></tr></tbody></table><h2 id="四、必背数字清单" tabindex="-1">四、必背数字清单 <a class="header-anchor" href="#四、必背数字清单" aria-label="Permalink to &quot;四、必背数字清单&quot;">​</a></h2><ul><li>市电电压(相电压)<strong>:220 V</strong>,线电压 <strong>380 V</strong></li><li>工频频率 <strong>50 Hz</strong>,周期 0.02 s</li><li>交流电最大值 = 有效值 × <strong>1.414</strong></li><li>三相星形:线电压 = 相电压 × <strong>1.732</strong></li><li><strong>1 度电 = 1 kWh = 3.6×10⁶ J</strong></li><li>常见功率单位换算:<strong>1 kW = 1000 W</strong></li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 单位符号要记牢:A(电流)、V(电压)、Ω(电阻)、W(功率)、J(焦耳)、Hz(频率)。</li><li>✅ 换算关系:1 kWh = 3.6×10⁶ J、1 MΩ = 10⁶ Ω。</li><li>✅ 220 V/380 V 都是有效值。</li><li>⚠️ 易混点:W 既可以指功率单位&quot;瓦特&quot;,也可以作为电功的符号(此时单位是 J),看题干上下文区分。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>名词表、单位表是&quot;工具书&quot;,学习后面章节随时回来查。</li><li>必背数字:220/380 V、50 Hz、√2≈1.414、√3≈1.732、1 度电=1 kWh。</li><li>区分好易混概念,是拿分的关键。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)下列单位中,表示电阻的单位是()。 A. A　B. V　C. Ω　D. W</li><li>(单选)1 kWh 等于()。 A. 1000 J　B. 3600 J　C. 3.6×10⁶ J　D. 3.6×10⁴ J</li><li>(判断)1 kV 等于 1000 V。( )</li><li>(单选)相电压 220 V 的星形三相系统,其线电压约为()。 A. 311 V　B. 380 V　C. 220 V　D. 127 V</li><li>(判断)功率的单位是瓦特(W)。( )</li><li>(单选)有效值为 220 V 的交流电,其最大值约为()。 A. 311 V　B. 220 V　C. 380 V　D. 155 V</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>C</strong>。电阻单位是欧姆(Ω);A 是电流单位,V 是电压单位,W 是功率单位。</li><li><strong>C</strong>。1 kWh = 1000 W × 3600 s = 3.6×10⁶ J。</li><li><strong>√</strong>。1 kV = 1000 V。</li><li><strong>B</strong>。星形接法线电压 = √3 × 相电压 = 1.732 × 220 ≈ 380 V。</li><li><strong>√</strong>。功率单位是瓦特(W)。</li><li><strong>A</strong>。最大值 = 有效值 × √2 = 220 × 1.414 ≈ 311 V。</li></ol></details>',18)])])}const V=d(l,[["render",o]]);export{u as __pageData,V as default};
